const int MOD = 998244353;

template<ll mod> // template was not stolen from https://codeforces.com/profile/SharpEdged
struct modnum {
    static constexpr bool is_big_mod = mod > numeric_limits<int>::max();

    using S = conditional_t<is_big_mod, ll, int>;
    using L = conditional_t<is_big_mod, __int128, ll>;

    S x;

    modnum() : x(0) {}
    modnum(ll _x) {
        _x %= static_cast<ll>(mod);
        if (_x < 0) { _x += mod; }
        x = _x;
    }

    modnum pow(ll n) const {
        modnum res = 1;
        modnum cur = *this;
        while (n > 0) {
            if (n & 1) res *= cur;
            cur *= cur;
            n /= 2;
        }
        return res;
    }
    modnum inv() const { return (*this).pow(mod-2); }

    modnum& operator+=(const modnum& a){
        x += a.x;
        if (x >= mod) x -= mod;
        return *this;
    }
    modnum& operator-=(const modnum& a){
        if (x < a.x) x += mod;
        x -= a.x;
        return *this;
    }
    modnum& operator*=(const modnum& a){
        x = static_cast<L>(x) * a.x % mod;
        return *this;
    }
    modnum& operator/=(const modnum& a){ return *this *= a.inv(); }

    friend modnum operator+(const modnum& a, const modnum& b){ return modnum(a) += b; }
    friend modnum operator-(const modnum& a, const modnum& b){ return modnum(a) -= b; }
    friend modnum operator*(const modnum& a, const modnum& b){ return modnum(a) *= b; }
    friend modnum operator/(const modnum& a, const modnum& b){ return modnum(a) /= b; }

    friend bool operator==(const modnum& a, const modnum& b){ return a.x == b.x; }
    friend bool operator!=(const modnum& a, const modnum& b){ return a.x != b.x; }
    friend bool operator<(const modnum& a, const modnum& b){ return a.x < b.x; }

    friend ostream& operator<<(ostream& os, const modnum& a){ os << a.x; return os; }
    friend istream& operator>>(istream& is, modnum& a) { ll x; is >> x; a = modnum(x); return is; }
};

using mint = modnum<MOD>;

void solve(){
    int n;
    cin >> n;

    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++){
        int u, v;
        cin >> u >> v;
        u--;
        v--;

        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (g[n - 1].size() == 1){
        cout << "1\n";
        return;
    }

    vector<int> mx(n);
    auto dfs = [&](auto self, int c, int p) -> void{
        for (int x : g[c]){
            if (x == p)
                continue;

            self(self, x, c);
            mx[c] = max({mx[c], x, mx[x]});
        }
    };
    dfs(dfs, n - 1, -1);

    set<int, greater<int>> s;
    for (int i = 0; i < n - 1; i++)
        s.insert(i);

    vector<int> cur;
    auto dfs2 = [&](auto self, int c, int p) -> void{
        s.erase(c);
        cur.push_back(c);

        for (int x : g[c]){
            if (x == p)
                continue;

            self(self, x, c);
        }
    };

    vector<bool> ok(n); // can transition to n
    for (int x : g[n - 1]){
        dfs2(dfs2, x, n - 1);

        for (int u : cur){
            if (u > (*s.begin()))
                ok[u] = true;
        }

        for (int u : cur)
            s.insert(u);
        cur.clear();
    }
    ok[n - 1] = true;

    int idx = -1;
    for (int i = 0; i < n; i++){
        if (g[i].size() == 1)
            idx = i;
    }

    vector<mint> dp(n), pre(n);
    dp[idx] = 1;
    pre[idx] = 1;
    for (int i = idx + 1; i < n - 1; i++){
        int l = mx[i] + 1;

        if (l < i){
            dp[i] = pre[i - 1];
            if (l > 0)
                dp[i] -= pre[l - 1];
        }

        pre[i] = dp[i] + pre[i - 1];
    }

    mint ans = 0;
    for (int i = 0; i < n; i++){
        if (ok[i])
            ans += dp[i];
    }

    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

