    modnum() : x(0) {}
    modnum(ll _x) {
        _x %= static_cast<ll>(mod);
        if (_x < 0) { _x += mod; }
        x = _x;
    }

    modnum pow(ll n) const {
        modnum res = 1;
        modnum cur = *this;
        while (n > 0) {
            if (n & 1) res *= cur;
            cur *= cur;
            n /= 2;
        }
        return res;
    }
    modnum inv() const { return (*this).pow(mod-2); }

    modnum& operator+=(const modnum& a){
        x += a.x;
        if (x >= mod) x -= mod;
        return *this;
    }
    modnum& operator-=(const modnum& a){
        if (x < a.x) x += mod;
        x -= a.x;
        return *this;
    }
    modnum& operator*=(const modnum& a){
        x = static_cast<L>(x) * a.x % mod;
        return *this;
    }
    modnum& operator/=(const modnum& a){ return *this *= a.inv(); }

    friend modnum operator+(const modnum& a, const modnum& b){ return modnum(a) += b; }
    friend modnum operator-(const modnum& a, const modnum& b){ return modnum(a) -= b; }
    friend modnum operator*(const modnum& a, const modnum& b){ return modnum(a) *= b; }
    friend modnum operator/(const modnum& a, const modnum& b){ return modnum(a) /= b; }

    friend bool operator==(const modnum& a, const modnum& b){ return a.x == b.x; }
    friend bool operator!=(const modnum& a, const modnum& b){ return a.x != b.x; }
    friend bool operator<(const modnum& a, const modnum& b){ return a.x < b.x; }

    friend ostream& operator<<(ostream& os, const modnum& a){ os << a.x; return os; }
    friend istream& operator>>(istream& is, modnum& a) { ll x; is >> x; a = modnum(x); return is; }
};

using mint = modnum<MOD>;

void solve(){
    int n;
    cin >> n;

    string s;
    cin >> s;

    s = '0' + s;
    n++;

    vector<int> pre(n);
    pre[0] = s[0] == '1';
    for (int i = 1; i < n; i++){
        pre[i] = pre[i - 1] + (s[i] == '1');
    }

    vector<array<array<int, 2>, 2>> to(n + 1);
    for (int i = 0; i <= n; i++){
        to[i][0][0] = n;
        to[i][0][1] = n;
        to[i][1][0] = n;
        to[i][1][1] = n;

        int cnt = 0;
        bool wowee = false;
        for (int j = i + 1; j < n; j++){
            if ((cnt & 1) && !wowee){
                if (s[j] == '1')
                    cnt++;
                if (s[j] == '?')
                    wowee = true;
                continue;
            }

            if (s[j] == '1')
                cnt++;
            if (s[j] == '?')
                wowee = true;

            int par = pre[j] & 1;
            if (s[j] == '?'){
                to[i][0][par] = min(to[i][0][par], j);
                to[i][1][par] = min(to[i][1][par], j);
                continue;
            }

            int omg = s[j] - '0';
            to[i][omg][par] = min(to[i][omg][par], j);
        }
    }

    vector<bool> good(n + 1);
    int cnt = 0;
    int wowee = false;
    for (int i = n - 1; i >= 0; i--){
        good[i] = (cnt % 2 == 0) || wowee;
        if (s[i] == '1')
            cnt++;
        if (s[i] == '?')
            wowee = true;
    }

    mint ans = 0;
    vector<vector<mint>> dp(n + 1, vector<mint>(n + 1));
    dp[0][n] = 1;

    vector<array<int, 2>> ord;
    for (int i = 0; i <= n; i++){
        for (int j = i; j <= n; j++){
            ord.push_back({i, j});
            if (j != i)
                ord.push_back({j, i});
        }
    }

    for (auto [i, j] : ord){
        for (int nxt = 0; nxt < 2; nxt++){
            int even = min(to[i][nxt][0], to[j][nxt][0]);
            int odd = min(to[i][nxt][1], to[j][nxt][1]);
            dp[even][odd] += dp[i][j];
        }

        if (good[i] || good[j])
            ans += dp[i][j];
    }

    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
